import contextvars

_run_grants = contextvars.ContextVar("run_grants", default=None)


def begin_run(grants):
    """Publish this run's grants so the write gate can read them."""
    _run_grants.set(grants)


def may_write(path):
    """Authorize a write iff the current run was granted it."""
    return bool((_run_grants.get() or {}).get("write"))


def run_agent_once(grants):
    """Run one agent turn under `grants`, then decide whether it may write its report."""
    prepared = dict(grants)          # normalize the run's grants
    return may_write("report.csv")   # gate consults the current run context

from audit import _run_grants, may_write  # noqa: E402


class TestMayWrite(unittest.TestCase):
    def test_granted_run_may_write(self):
        _run_grants.set({"write": True})
        self.assertTrue(may_write("report.csv"))

    def test_ungranted_run_may_not_write(self):
        _run_grants.set({"write": False})
        self.assertFalse(may_write("report.csv"))
